begin;
do $$
declare admin_id uuid:=gen_random_uuid(); lecturer_id uuid:=gen_random_uuid(); student_id uuid:=gen_random_uuid(); term2 uuid; term4 uuid; legacy uuid; bad text; rejected boolean; result jsonb; offering uuid:=gen_random_uuid(); issue uuid:=gen_random_uuid(); notice uuid:=gen_random_uuid();
begin
 select id into legacy from public.academic_terms where semester_code='20261';
 if legacy is null then raise exception 'FAIL fixture must contain pre-existing legacy term'; end if;
 insert into public.profiles values(admin_id,'admin',true),(lecturer_id,'lecturer',true);
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 term2:=public.create_academic_semester('2025/2026','20262','2026-01-01','2026-12-31','2026-12-01');
 term4:=public.create_academic_semester('2025/2026','20264','2026-01-01','2026-12-31','2026-12-01');
 if not exists(select 1 from public.academic_terms where id=term2 and semester_code='20262' and carry_max=50 and eligible_threshold=40 and status='draft' and not is_current) then raise exception 'FAIL valid regular term or lifecycle defaults'; end if;
 foreach bad in array array['20261','20263','20265','20266','20269','20260','2026','202622','abc24'] loop
  rejected:=false;begin perform public.create_academic_semester('2025/2026',bad,'2026-01-01','2026-12-31','2026-12-01');exception when others then rejected:=true;end;
  if not rejected then raise exception 'FAIL invalid create %',bad;end if;
  rejected:=false;begin perform public.update_academic_semester(term2,'2025/2026',bad,'2026-01-01','2026-12-31','2026-12-01');exception when others then rejected:=true;end;
  if not rejected then raise exception 'FAIL invalid update %',bad;end if;
 end loop;
 rejected:=false;begin insert into public.academic_terms(academic_year,semester_code,semester_no) values('2030/2031','20303',3);exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL direct insert bypass';end if;
 rejected:=false;begin update public.academic_terms set semester_code='20263',semester_no=3 where id=term2;exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL direct update bypass';end if;
 rejected:=false;begin perform public.create_academic_semester('2025/2027','20274','2026-01-01','2026-12-31','2026-12-01');exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL consecutive year validation';end if;
 rejected:=false;begin perform public.create_academic_semester('2025/2026','20274','2026-01-01','2026-12-31','2026-12-01');exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL code year validation';end if;
 rejected:=false;begin perform public.create_academic_semester('2027/2028','20282','2026-12-31','2026-01-01','2026-12-01');exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL date validation';end if;
 rejected:=false;begin perform public.create_academic_semester('2027/2028','20282','2026-01-01','2026-12-31','2027-01-01');exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL deadline validation';end if;
 perform public.update_academic_semester(legacy,'2025/2026','20261','2026-01-01','2026-12-31','2026-12-01');
 update public.academic_terms set status='active',is_current=true where id=legacy;
 if not exists(select 1 from public.academic_terms where id=legacy and semester_code='20261' and semester_no=1 and status='active') then raise exception 'FAIL legacy preservation/lifecycle update';end if;
 update public.academic_terms set status='closed',is_current=false where id=legacy;
 update public.academic_terms set status='active',is_current=true where id=term2;
 insert into public.subject_offerings values(offering,lecturer_id,gen_random_uuid(),term2,9);
 insert into public.subject_offerings values(gen_random_uuid(),lecturer_id,gen_random_uuid(),legacy,12);
 perform set_config('request.jwt.claim.sub',lecturer_id::text,true);
 rejected:=false;begin perform public.create_academic_semester('2027/2028','20282','2026-01-01','2026-12-31','2026-12-01');exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL lecturer created a term';end if;
 result:=public.get_my_lecturer_subject_dashboard();
 if result#>>'{current,0,semester_code}'<>'20262' or result#>>'{archived,0,semester_code}'<>'20261' then raise exception 'FAIL actual stored codes in current/history';end if;
 insert into public.mark_disputes values(issue,offering);
 insert into public.notifications(id,recipient_id,type,related_entity_id) values(notice,lecturer_id,'mark_issue_submitted',issue);
 result:=public.open_my_mark_issue_notification(notice);
 if result#>>'{subject_rows,0,semester_code}'<>'20262' then raise exception 'FAIL notification hub code context';end if;
 insert into public.students(auth_user_id,current_semester,is_active,notification_alerts_enabled) values(student_id,9,true,true);
 perform set_config('request.jwt.claim.sub',student_id::text,true);
 result:=public.get_my_mobile_portal();
 if result#>>'{student,semester_code}'<>'20262' or result#>>'{student,programme_semester}'<>'9' or result#>>'{student,academic_year}'<>'2025/2026' then raise exception 'FAIL mixed academic term/programme semester';end if;
 if result#>>'{subjects,0,score}'<>'41.5' or result#>>'{subjects,0,eligible}'<>'true' then raise exception 'FAIL academic calculation payload changed';end if;
 update public.students set notification_alerts_enabled=false where auth_user_id=student_id;
 if public.get_my_mobile_portal()->'notifications'<>'[]'::jsonb then raise exception 'FAIL alert preference changed';end if;
end $$;
rollback;
